        <script id="lentille-context" type="application/json">{"instance":"main","template":"article.show","status":200,"locale":"zh-CN","data":{"article":{"lid":"fhjk4bvl","title":"\u9898\u89e3\uff1aP14637 [NOIP2025] \u6811\u7684\u4ef7\u503c \/ tree\uff08\u6c11\u95f4\u6570\u636e\uff09","category":2,"time":1764578599,"author":{"uid":21784,"avatar":"https:\/\/cdn.luogu.com.cn\/upload\/usericon\/21784.png","name":"Caii","slogan":"","badge":null,"isAdmin":false,"isBanned":false,"color":"Blue","ccfLevel":0,"xcpcLevel":0,"background":""},"upvote":40,"replyCount":27,"favorCount":2,"status":2,"solutionFor":{"pid":"P14637","type":"P","name":"[NOIP2025] \u6811\u7684\u4ef7\u503c","difficulty":8,"fullScore":100},"promoteStatus":2,"collection":null,"content":"\u7ea6\u5b9a\uff1a\n\n- \u5bf9\u4e8e\u4e00\u4e2a\u8282\u70b9 $x$\uff0c\u5982\u679c $x$ \u53d6\u503c\u5bf9 $x$ \u7684 ${\\rm mex}$ \u6709\u8d21\u732e\uff0c\u6211\u4eec\u79f0 $x$ \u662f\u4e00\u4e2a**\u7ea2\u70b9**\u3002\n- \u5bf9\u4e8e\u4e00\u4e2a\u8282\u70b9 $x$\uff0c\u5982\u679c $x$ \u53d6\u503c\u5bf9 $x$ \u7684 ${\\rm mex}$ \u6ca1\u6709\u8d21\u732e\uff0c\u6211\u4eec\u79f0 $x$ \u662f\u4e00\u4e2a**\u84dd\u70b9**\u3002\n\n![](https:\/\/cdn.luogu.com.cn\/upload\/image_hosting\/1jfs446x.png)\n\n\u5982\u4e0a\u56fe\u6240\u793a\uff1a\n\n- \u7ea2\u70b9 $x$ \u7684\u8d21\u732e = $x$ \u5230\u6839\u8def\u5f84\u4e0a\u8fde\u7eed\u7ea2\u70b9\u6bb5\u957f\u5ea6 + \u7ea2\u70b9\u6bb5\u4e4b\u540e\u8fde\u7eed\u84dd\u70b9\u6bb5\u957f\u5ea6\u3002\n\n  \u4f46\u662f\uff0c\u84dd\u70b9\u6bb5\u8d21\u732e\u53ea\u80fd\u88ab\u4e00\u6bb5\u7ea2\u70b9\u6240\u4eab\u6709\uff0c\u4f8b\u5982\u4e2d\u95f4\u56fe\uff0c\u70b9 $7$ \u548c\u70b9 $8$ \u7684\u8def\u5f84\u4e0a\u90fd\u6709\u84dd\u70b9 $3$\uff0c\u6b64\u65f6\u70b9 $3$ \u7684\u8d21\u732e\u53ea\u80fd\u88ab\u4e00\u6bb5\u4eab\u6709\uff0c\u56e0\u6b64 $7$ \u7684\u8d21\u732e\u4e3a $2$\uff0c$8$ \u7684\u8d21\u732e\u4e3a $1$\u3002\n\n  \u7531\u4e0a\u9762\u8fd9\u4e00\u70b9\uff0c\u6211\u4eec\u53ef\u4ee5\u89c4\u5b9a\u4e00\u4e2a\u70b9\u6700\u591a\u53ea\u6709\u4e00\u4e2a\u7ea2\u70b9\u513f\u5b50\uff0c\u56e0\u4e3a\u591a\u4e2a\u7ea2\u70b9\u513f\u5b50\uff0c\u5fc5\u7136\u7531\u7ea2\u70b9\u513f\u5b50\u8d21\u732e\u4e3a $1$\uff0c\u5c06\u5176\u53d8\u6210\u84dd\u70b9\u4e0d\u4f1a\u53d8\u5dee\u3002\n\n- \u84dd\u70b9 $x$ \u7684\u8d21\u732e = $x$ \u7956\u5148\u7b2c\u4e00\u4e2a\u7ea2\u70b9\u7684\u8d21\u732e\n\n  \u4f8b\u5982 $5$ \u7684\u8d21\u732e\u4e3a $2$\uff0c\u56e0\u4e3a $5$ \u7684\u7956\u5148\u4e2d\u7b2c\u4e00\u4e2a\u7ea2\u70b9\u4e3a $2$\uff0c\u5176\u8d21\u732e\u4e3a $2$\u3002\n\n\u8bbe $f(x, k)$ \u8868\u793a\u7ea2\u70b9 $x$ \u8d21\u732e\u4e3a $k$ \u65f6\uff0c$x$ \u5b50\u6811\u7684\u6700\u5927\u8d21\u732e\u548c\uff1b$g(x, k)$ \u8868\u793a\u84dd\u70b9 $x$ \u8d21\u732e\u4e3a $k$ \u65f6\uff0c$x$ \u5b50\u6811\u7684\u6700\u5927\u8d21\u732e\u548c\u3002\n\n\u5bf9\u4e8e\u7ea2\u70b9\uff0c\u6bcf\u4e2a\u70b9\u53ea\u6709\u4e00\u4e2a\u7ea2\u70b9\u513f\u5b50\uff0c\u5176\u4ed6\u90fd\u662f\u84dd\u70b9\u513f\u5b50\uff0c\u800c\u6839\u636e\u84dd\u70b9\u8d21\u732e\u8ba1\u7b97\u65b9\u5f0f\u53ef\u77e5\u8fd9\u4e9b\u84dd\u70b9\u513f\u5b50\u7684\u8d21\u732e\u4e0e $x$ \u662f\u4e00\u6837\u7684\u3002\u5b9e\u9645\u4e0a\u901a\u8fc7\u8fd9\u4e00\u70b9\u4e5f\u53ef\u4ee5\u8bf4\u660e\u5982\u679c $x$ \u6709\u513f\u5b50\u5219\u5fc5\u6709\u7ea2\u70b9\u513f\u5b50\uff0c\u56e0\u4e3a\u7ea2\u70b9\u513f\u5b50\u8d21\u732e\u4e3a $x$ \u8d21\u732e $+1$\u3002\u8f6c\u79fb\u4e3a\uff1a\n$$\nf(x, k)=\\max_{1\\leq i\\leq t}\\left\\{f(x_i, k+1)+\\sum_{j\\neq i}g(x_j, k)+k\\right\\}\n$$\n\u5bf9\u4e8e\u84dd\u70b9 $x$\uff0c\u5148\u8003\u8651\u7b80\u5355\u7684\u60c5\u51b5\uff1a\u5982\u679c $x$ \u5b50\u6811\u4e2d\u90fd\u662f\u84dd\u70b9\uff0c\u5219\n$$\ng(x, k)\\leftarrow k+\\sum_{1\\leq i\\leq t}g(x_i, k)\n$$\n\u5982\u679c $x$ \u5b50\u6811\u4e2d\u5b58\u5728\u7ea2\u70b9\uff0c\u5219\u4f1a\u590d\u6742\u4e00\u4e9b\uff0c\u56e0\u4e3a $x$ \u5b50\u6811\u4e2d\u53ea\u6709\u4e00\u6bb5\u7ea2\u70b9\u53ef\u4ee5\u4eab\u6709 $x$ \u8fd9\u4e2a\u84dd\u70b9\u6bb5\u7684\u8d21\u732e\uff0c\u6211\u4eec\u8981\u8ba1\u7b97\u8fd9\u4e2a\u8d21\u732e\uff0c\u4e0d\u59a8\u8bbe\u8fd9\u4e2a\u70b9\u4e3a $v$\uff0c\u5219 DP \u503c\u4e3a $x$ \u5b50\u6811\u4e2d\u9664\u5b50\u6811 $v$ \u5916\u6240\u6709\u70b9\u8d21\u732e\u4e4b\u548c\u6700\u5927\u503c\u52a0\u4e0a $v$ \u7684\u8d21\u732e\u3002\n\n![](https:\/\/cdn.luogu.com.cn\/upload\/image_hosting\/agh56mxk.png)\n\n\u5982\u4e0a\u56fe\u6240\u793a\uff0c\u8fd9\u4e2a\u56fe\u6709\u5f88\u591a\u6027\u8d28\uff1a\n\n- $x$ \u5230 $v$ \u94fe\u4e0a\u6240\u6709\u70b9\u90fd\u662f\u84dd\u70b9\uff0c\u5426\u5219 $v$ \u65e0\u6cd5\u4eab\u53d7\u5230 $x$ \u8fd9\u4e2a\u84dd\u8272\u6bb5\u7684\u8d21\u732e\u3002\n\n- $x$ \u5230 $v$ \u94fe\u4e0a\u5176\u4ed6\u513f\u5b50 $\\alpha, \\beta, \\gamma, \\eta$ \u90fd\u662f\u84dd\u70b9\uff0c\u5982\u679c\u8fd9\u4e9b\u70b9\uff0c\u4f8b\u5982 $\\gamma_1$ \u662f\u7ea2\u70b9\uff0c\u5219\u56e0\u4e3a $\\gamma_1$ \u65e0\u6cd5\u4eab\u53d7\u5230 $x$ \u8fd9\u4e2a\u84dd\u8272\u6bb5\u7684\u8d21\u732e\uff0c\u6240\u4ee5 $\\gamma_1$ \u65e0\u6cd5\u4eab\u53d7\u5230\u6574\u4e2a\u84dd\u8272\u6bb5\u8d21\u732e\uff0c\u56e0\u6b64\u8d21\u732e\u4e3a $1$\uff0c\u628a $\\gamma_1$ \u53d8\u6210\u84dd\u70b9\u8d21\u732e\u4e0d\u4f1a\u53d8\u5dee\u3002\n\n- $x$ \u5230 $v$ \u94fe\u4e0a\u6240\u6709\u84dd\u70b9\u8d21\u732e\u5747\u4e3a $k$\u3002\n\n- $v$ \u7684\u8d21\u732e\u4e3a $k+1$\u3002\n\n  \u5982\u679c $v$ \u7684\u8d21\u732e\u5927\u4e8e $k+1$\uff0c\u5219\u53ef\u4ee5\u5c06 $v$ \u7684\u7236\u4eb2\u53d8\u6210\u7ea2\u70b9\uff0c\u5176\u65b0\u7684\u8d21\u732e\u4e3a $v$ \u7684\u8d21\u732e\u51cf\u53bb $1$\uff0c\u5927\u4e8e $k$\uff0c\u66f4\u4f18\u3002\u56e0\u6b64 $v$ \u7684\u8d21\u732e\u4e0d\u8d85\u8fc7 $k+1$\u3002\n\n  \u5982\u679c $v$ \u7684\u8d21\u732e\u5c0f\u4e8e $k+1$\uff0c\u5219\u5c06 $v$ \u53d8\u6210\u84dd\u70b9\u8d21\u732e\u4e0d\u4f1a\u53d8\u5dee\u3002\n\n  \u7efc\u4e0a\uff1a$v$ \u8d21\u732e\u4e3a $k+1$\u3002\u5b9e\u9645\u4e0a\u6839\u636e\u4e0a\u9762\u7684\u5206\u6790 $v$ \u7684\u8d21\u732e\u4e3a $k$ \u4e5f\u662f\u4f18\u7684\uff0c\u4f46\u662f\u5b58\u5728\u4f8b\u5916\u60c5\u51b5\uff0c\u4f8b\u5982\u7b2c\u4e00\u5f20\u56fe\u70b9 $7$ \u7684\u8d21\u732e\u53ea\u80fd\u4e3a $2$\uff0c\u4e0d\u80fd\u4e3a $1$\u3002\n\n- \u6839\u636e\u7ea2\u70b9\u8d21\u732e\u8ba1\u7b97\u65b9\u5f0f\uff0c$v$ \u7684\u8d21\u732e\u4e3a ${\\rm dep}(v)-{\\rm dep}(x)+1$\uff0c\u56e0\u6b64 $k={\\rm dep}(v)-{\\rm dep}(x)$\u3002\n\n\u7efc\u4e0a\uff0c\u8f6c\u79fb\u65b9\u7a0b\u4e3a \n$$\ng(x, k)\\leftarrow k+f(v, k+1)+\\sum_{c\u5728x\u5230v\u8def\u5f84\u4e0a\uff0c\u662fx\u5230v\u8def\u5f84\u4e0a\u9664v\u5916\u67d0\u4e2a\u70b9\u7684\u513f\u5b50}g(c, k)\n$$\n\u6211\u4eec\u8981\u7ef4\u62a4\u540e\u9762\u7684\u90a3\u4e2a\u6c42\u548c\uff0c\u53ef\u4ee5\u4f7f\u7528\u6570\u636e\u7ed3\u6784\uff0c\u4f8b\u5982 DP \u5230 $x$ \u5230 $v$ \u8def\u5f84\u4e0a\u4e00\u4e2a\u70b9 $y$ \u65f6\uff0c\u8bbe\u5176\u6709 $r$ \u4e2a\u513f\u5b50 $z_1, z_2, \\cdots, z_r$\uff0c\u6211\u4eec\u5bf9\u4e8e $1\\leq i\\leq r$\uff0c\u5bf9 $z_i$ \u5b50\u6811\u5185\u6240\u6709\u70b9\u7684 $f(\\cdot, k+1)$  \u503c\u52a0\u4e0a $\\sum_{j\\neq i}g(z_j, k)$\uff0c\u8fd9\u6837\u5c31\u80fd\u5feb\u901f\u8ba1\u7b97 DP \u503c\u4e86\u3002\u9700\u8981\u533a\u95f4\u52a0\uff0c\u5355\u70b9\u67e5\uff0c\u53ef\u4ee5\u4f7f\u7528\u6811\u72b6\u6570\u7ec4\u3002\n\n\u6700\u540e\u7b54\u6848\u4e3a $f(1, 1)$\uff0c\u65f6\u95f4\u590d\u6742\u5ea6\u4e3a $O(nm\\log n)$\u3002\n\n```cpp\n#include \u003Cbits\/stdc++.h\u003E\n\nconst int N = 8000 + 7;\nconst int M = 800 + 7;\n\nstd::vector\u003Cint\u003E e[N];\nint bit[M][N], f[N][M], g[N][M], n, m;\nint dfn[N], nfd[N], ed[N], cdfn, dep[N];\n\nvoid add(int *bit, int x, int v) {\n  while(x \u003C= n) {\n    bit[x] += v;\n    x += x \u0026 -x;\n  }\n}\n\nint ask(int *bit, int x) {\n  int ret = 0;\n  while(x) {\n    ret += bit[x];\n    x -= x \u0026 -x;\n  }\n  return ret;\n}\n\nvoid dfs(int x) {\n  dfn[x] = ++cdfn;\n  nfd[cdfn] = x;\n  for(int v: e[x]) {\n    dep[v] = dep[x] + 1;\n    dfs(v);\n  }\n  ed[x] = cdfn;\n  for(int i = 1; i \u003C= dep[x]; ++i) {\n    f[x][i] = g[x][i] = i;\n    for(int v: e[x])\n      g[x][i] += g[v][i];\n    for(int v: e[x])\n      f[x][i] = std::max(f[x][i], f[v][i + 1] + g[x][i] - g[v][i]);\n    for(int v: e[x]) {\n      add(bit[i], dfn[v], g[x][i] - g[v][i]);\n      add(bit[i], ed[v] + 1, g[v][i] - g[x][i]);\n    }\n  }\n  for(int j = dfn[x] + 1; j \u003C= ed[x]; ++j) {\n    int i = dep[nfd[j]] - dep[x] + 1;\n    g[x][i - 1] = std::max(g[x][i - 1], ask(bit[i - 1], j) + f[nfd[j]][i]);\n  }\n}  \n\nvoid solve() {\n  scanf(\u0022%d%d\u0022, \u0026n, \u0026m);\n  for(int i = 1; i \u003C= n; ++i)\n    e[i].clear();\n  for(int i = 2, x; i \u003C= n; ++i) {\n    scanf(\u0022%d\u0022, \u0026x);\n    e[x].push_back(i);\n  }\n  memset(bit, 0, sizeof bit);\n  cdfn = 0;\n  dep[1] = 1;\n  dfs(1);\n  printf(\u0022%d\\n\u0022, f[1][1]);\n}\n    \nint main() {\n\n  freopen(\u0022tree.in\u0022, \u0022r\u0022, stdin);\n  freopen(\u0022tree.out\u0022, \u0022w\u0022, stdout);\n\n  int cases;\n  scanf(\u0022%d\u0022, \u0026cases);\n\n  while(cases--)\n    solve();\n     \n  return 0;\n}\n\n```","contentFull":true,"adminNote":null},"favored":false,"voted":null,"canReply":false,"canEdit":false},"user":null,"time":1793774030.266183}</script>            <script src="https://fecdn.luogu.com.cn/columba/loader.20261018-2305.js" charset="utf-8" defer></script>
